import { totalCents, type Order } from "../core/order.js";
import type { OrderPage } from "../core/orderService.js";
import { encodeCursor } from "./cursor.js";

/** Body of `GET /orders/{id}` (200). Also returned by `POST /orders` and `POST /orders/{id}/cancel`. */
export interface OrderResponse {
  readonly id: string;
  readonly status: string;
  readonly placedAt: string;
  readonly currency: string;
  readonly totalCents: number;
  readonly lines: ReadonlyArray<{
    readonly sku: string;
    readonly name: string;
    readonly qty: number;
    readonly unitPriceCents: number;
  }>;
}

export interface OrderListResponse {
  readonly orders: readonly OrderResponse[];
  /** Pass as `cursor` to fetch the next page; absent on the last page. */
  readonly nextCursor?: string;
}

/** The single place where an order is mapped to its REST representation. */
export function toOrderResponse(order: Order): OrderResponse {
  return {
    id: order.id,
    status: order.status,
    placedAt: order.placedAt,
    currency: order.currency,
    totalCents: totalCents(order),
    lines: order.lines.map((line) => ({
      sku: line.sku,
      name: line.name,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
  };
}

export function toOrderListResponse(page: OrderPage): OrderListResponse {
  const orders = page.orders.map(toOrderResponse);
  return page.next === undefined ? { orders } : { orders, nextCursor: encodeCursor(page.next) };
}
import { totalCents, type Channel, type Order } from "./order.js";

export const ORDER_PLACED_TOPIC = "orders.placed";
export const ORDER_CANCELLED_TOPIC = "orders.cancelled";

/** Published when an order has been accepted and its payment authorized. */
export interface OrderPlaced {
  readonly type: "OrderPlaced";
  readonly schemaVersion: 3;
  readonly orderId: string;
  readonly customerId: string;
  /** Legacy field; a known ARCH-6 exception tracked in the PII baseline. */
  readonly customerEmail: string;
  /** ISO-8601 instant. */
  readonly placedAt: string;
  readonly channel: Channel;
  /** ISO-4217 code. */
  readonly currency: string;
  /** Integer, minor units. */
  readonly totalCents: number;
  readonly lines: ReadonlyArray<{
    readonly sku: string;
    readonly qty: number;
    readonly unitPriceCents: number;
  }>;
}

/** Published when a placed order is cancelled. */
export interface OrderCancelled {
  readonly type: "OrderCancelled";
  readonly schemaVersion: 1;
  readonly orderId: string;
  readonly customerId: string;
  /** ISO-8601 instant. */
  readonly cancelledAt: string;
  readonly reason?: string;
}

export type DomainEvent = OrderPlaced | OrderCancelled;

/** The single place where an `OrderPlaced` event is built. */
export function orderPlaced(order: Order): OrderPlaced {
  return {
    type: "OrderPlaced",
    schemaVersion: 3,
    orderId: order.id,
    customerId: order.customerId,
    customerEmail: order.customerEmail,
    placedAt: order.placedAt,
    channel: order.channel,
    currency: order.currency,
    totalCents: totalCents(order),
    lines: order.lines.map((line) => ({
      sku: line.sku,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
  };
}

/** The single place where an `OrderCancelled` event is built. */
export function orderCancelled(order: Order, cancelledAt: string, reason?: string): OrderCancelled {
  return {
    type: "OrderCancelled",
    schemaVersion: 1,
    orderId: order.id,
    customerId: order.customerId,
    cancelledAt,
    ...(reason === undefined ? {} : { reason }),
  };
}

export function topicFor(event: DomainEvent): string {
  switch (event.type) {
    case "OrderPlaced":
      return ORDER_PLACED_TOPIC;
    case "OrderCancelled":
      return ORDER_CANCELLED_TOPIC;
  }
}

/** Partition key: all events of one order are ordered relative to each other. */
export function partitionKeyFor(event: DomainEvent): string {
  return event.orderId;
}
/**
 * Money is an integer amount in minor units (cents for USD/EUR) plus an ISO-4217 currency.
 * Floating point amounts never enter the domain.
 */

export interface Money {
  readonly amountMinor: number;
  readonly currency: string;
}

/** Number of decimal digits of the minor unit for every currency the service accepts. */
const MINOR_UNIT_DIGITS: Readonly<Record<string, number>> = {
  USD: 2,
  EUR: 2,
  GBP: 2,
  CAD: 2,
  AUD: 2,
  MXN: 2,
  CHF: 2,
  SEK: 2,
  JPY: 0,
  KRW: 0,
};

export const SUPPORTED_CURRENCIES: readonly string[] = Object.keys(MINOR_UNIT_DIGITS);

export function isSupportedCurrency(code: unknown): code is string {
  return typeof code === "string" && Object.hasOwn(MINOR_UNIT_DIGITS, code);
}

/** True for a non-negative integer that is exactly representable (a valid minor-unit amount). */
export function isMinorUnits(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function minorUnitDigits(currency: string): number {
  const digits = MINOR_UNIT_DIGITS[currency];
  if (digits === undefined) {
    throw new RangeError(`Unsupported currency: ${currency}`);
  }
  return digits;
}

export function money(amountMinor: number, currency: string): Money {
  if (!isMinorUnits(amountMinor)) {
    throw new RangeError(`Amount must be a non-negative integer in minor units, got ${amountMinor}`);
  }
  if (!isSupportedCurrency(currency)) {
    throw new RangeError(`Unsupported currency: ${currency}`);
  }
  return { amountMinor, currency };
}

export function zero(currency: string): Money {
  return money(0, currency);
}

export function add(a: Money, b: Money): Money {
  assertSameCurrency(a, b);
  return money(a.amountMinor + b.amountMinor, a.currency);
}

export function multiply(m: Money, quantity: number): Money {
  if (!Number.isSafeInteger(quantity) || quantity < 0) {
    throw new RangeError(`Quantity must be a non-negative integer, got ${quantity}`);
  }
  return money(m.amountMinor * quantity, m.currency);
}

export function sum(items: readonly Money[], currency: string): Money {
  return items.reduce((total, item) => add(total, item), zero(currency));
}

function assertSameCurrency(a: Money, b: Money): void {
  if (a.currency !== b.currency) {
    throw new RangeError(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  }
}
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { OrderCancelled, OrderPlaced } from "../src/core/events.js";
import { FIXED_NOW, FakePayments, makeApp, placeOrderBody } from "./helpers.js";

describe("POST /orders", () => {
  it("places an order, answers 201 and publishes OrderPlaced v3", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle("POST", "/orders", placeOrderBody());

    assert.equal(res.status, 201);
    assert.deepEqual(res.body, {
      id: "ord-1",
      status: "placed",
      placedAt: FIXED_NOW,
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
    });
    assert.equal(publisher.events.length, 1);
    assert.deepEqual(publisher.events[0], {
      type: "OrderPlaced",
      schemaVersion: 3,
      orderId: "ord-1",
      customerId: "cust-1",
      customerEmail: "jane@example.com",
      placedAt: FIXED_NOW,
      channel: "web",
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", qty: 2, unitPriceCents: 625 }],
    } satisfies OrderPlaced);
    assert.deepEqual(payments.requests, [
      { orderId: "ord-1", customerId: "cust-1", amountMinor: 1250, currency: "USD" },
    ]);
  });

  it("handles a multi-line order with a total of 2497 cents", async () => {
    const { app, publisher } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({
        lines: [
          { sku: "CAB-1", name: "Cable", qty: 3, unitPriceCents: 499 },
          { sku: "ADP-1", name: "Adapter", qty: 1, unitPriceCents: 1000 },
        ],
      }),
    );
    assert.equal(res.status, 201);
    assert.equal((publisher.events[0] as OrderPlaced).totalCents, 2497);
  });

  it("answers 400 with every issue for an invalid body and publishes nothing", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({ currency: "ZZZ", lines: [{ sku: "SKU-1", name: "x", qty: 0, unitPriceCents: 100 }] }),
    );
    assert.equal(res.status, 400);
    const error = (res.body as { error: { code: string; details: Array<{ path: string }> } }).error;
    assert.equal(error.code, "validation_failed");
    assert.deepEqual(error.details.map((d) => d.path), ["currency", "lines[0].qty"]);
    assert.equal(publisher.events.length, 0);
    assert.equal(payments.requests.length, 0);
  });

  it("answers 400 for wrong types and a missing body", async () => {
    const { app } = makeApp();
    const wrongType = await app.handle("POST", "/orders", placeOrderBody({ customerId: 42, lines: "none" }));
    assert.equal(wrongType.status, 400);
    const missing = await app.handle("POST", "/orders", undefined);
    assert.equal(missing.status, 400);
  });

  it("answers 402 when the payment is declined and keeps nothing", async () => {
    const { app, publisher } = makeApp(new FakePayments({ authorized: false, declineReason: "card_expired" }));
    const res = await app.handle("POST", "/orders", placeOrderBody());
    assert.equal(res.status, 402);
    assert.equal(publisher.events.length, 0);
    assert.equal((await app.handle("GET", "/orders/ord-1")).status, 404);
  });
});

describe("GET /orders/{id}", () => {
  it("returns the stored order", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    const res = await app.handle("GET", "/orders/ord-1");
    assert.equal(res.status, 200);
    assert.deepEqual(Object.keys(res.body as object), ["id", "status", "placedAt", "currency", "totalCents", "lines"]);
  });

  it("answers 404 for an unknown order", async () => {
    const { app } = makeApp();
    const res = await app.handle("GET", "/orders/nope");
    assert.equal(res.status, 404);
    assert.equal((res.body as { error: { code: string } }).error.code, "order_not_found");
  });
});

describe("POST /orders/{id}/cancel", () => {
  it("cancels a placed order and publishes OrderCancelled", async () => {
    const { app, publisher, clock } = makeApp();
    await app.handle(
      "POST",
      "/orders",
      placeOrderBody({
        channel: "marketplace",
        currency: "EUR",
        lines: [{ sku: "EU-1", name: "Mug", qty: 1, unitPriceCents: 1990 }],
      }),
    );
    clock.advance(60_000);
    const res = await app.handle("POST", "/orders/ord-1/cancel", { reason: "customer request" });

    assert.equal(res.status, 200);
    assert.equal((res.body as { status: string }).status, "cancelled");
    assert.deepEqual(publisher.events[1], {
      type: "OrderCancelled",
      schemaVersion: 1,
      orderId: "ord-1",
      customerId: "cust-1",
      cancelledAt: "2026-10-10T12:01:00.000Z",
      reason: "customer request",
    } satisfies OrderCancelled);
  });

  it("answers 409 when the order is already cancelled and 404 when it does not exist", async () => {
    const { app, publisher } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel")).status, 200);
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel")).status, 409);
    assert.equal((await app.handle("POST", "/orders/ord-9/cancel")).status, 404);
    assert.equal(publisher.events.length, 2);
  });

  it("rejects a malformed body", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel", { reason: 5 })).status, 400);
  });
});

describe("GET /orders", () => {
  it("lists a customer's orders newest first and filters by status", async () => {
    const { app, clock } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    clock.advance(1000);
    await app.handle("POST", "/orders", placeOrderBody());
    clock.advance(1000);
    await app.handle("POST", "/orders", placeOrderBody({ customerId: "cust-2" }));
    await app.handle("POST", "/orders/ord-1/cancel");

    const all = await app.handle("GET", "/orders?customerId=cust-1");
    assert.equal(all.status, 200);
    const ids = (all.body as { orders: Array<{ id: string }> }).orders.map((o) => o.id);
    assert.deepEqual(ids, ["ord-2", "ord-1"]);

    const placed = await app.handle("GET", "/orders?customerId=cust-1&status=placed&limit=5");
    assert.deepEqual((placed.body as { orders: Array<{ id: string }> }).orders.map((o) => o.id), ["ord-2"]);
  });

  it("pages with an opaque cursor", async () => {
    const { app, clock } = makeApp();
    for (let i = 0; i < 3; i += 1) {
      await app.handle("POST", "/orders", placeOrderBody());
      clock.advance(1000);
    }
    type Page = { orders: Array<{ id: string }>; nextCursor?: string };
    const first = (await app.handle("GET", "/orders?customerId=cust-1&limit=2")).body as Page;
    assert.deepEqual(first.orders.map((o) => o.id), ["ord-3", "ord-2"]);
    assert.ok(first.nextCursor);
    const second = (await app.handle("GET", `/orders?customerId=cust-1&limit=2&cursor=${first.nextCursor}`)).body as Page;
    assert.deepEqual(second.orders.map((o) => o.id), ["ord-1"]);
    assert.equal(second.nextCursor, undefined);
    assert.equal((await app.handle("GET", "/orders?customerId=cust-1&cursor=garbage")).status, 400);
  });

  it("rejects a missing customer, an unknown status and a bad limit", async () => {
    const { app } = makeApp();
    assert.equal((await app.handle("GET", "/orders")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&status=lost")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&limit=abc")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&limit=500")).status, 400);
  });
});

describe("routing", () => {
  it("answers the liveness probe", async () => {
    const { app } = makeApp();
    assert.deepEqual(await app.handle("GET", "/health"), { status: 200, body: { status: "ok" } });
  });

  it("answers 405 for a known path with the wrong method and 404 for unknown paths", async () => {
    const { app } = makeApp();
    assert.equal((await app.handle("DELETE", "/orders/ord-1")).status, 405);
    assert.equal((await app.handle("DELETE", "/orders")).status, 405);
    assert.equal((await app.handle("GET", "/carts/1")).status, 404);
    assert.equal((await app.handle("GET", "/orders/ord-1/refund")).status, 404);
  });

  it("ignores query strings and trailing slashes", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    assert.equal((await app.handle("get", "/orders/ord-1/?verbose=1")).status, 200);
  });
});
import { InMemoryOrderRepository } from "./adapters/inMemoryOrderRepository.js";
import { KafkaEventPublisher } from "./adapters/kafkaEventPublisher.js";
import { HttpPaymentGateway } from "./adapters/httpPaymentGateway.js";
import { RandomIdGenerator } from "./adapters/randomIdGenerator.js";
import { SystemClock } from "./adapters/systemClock.js";
import { createOrdersController } from "./api/ordersController.js";
import { OrderService } from "./core/orderService.js";
import type { Clock, EventPublisher, IdGenerator, OrderRepository, PaymentGateway } from "./core/ports.js";

/** Every dependency is optional; omitted ones fall back to the production adapters. */
export interface AppDeps {
  readonly orderRepository?: OrderRepository;
  readonly eventPublisher?: EventPublisher;
  readonly paymentGateway?: PaymentGateway;
  readonly clock?: Clock;
  readonly idGenerator?: IdGenerator;
}

export interface App {
  /** Handles one request. Never rejects: failures become 4xx/5xx responses. */
  handle(method: string, path: string, body?: unknown): Promise<{ status: number; body: unknown }>;
  /** The publisher the app writes to (the injected one, or the default buffering publisher). */
  events: EventPublisher;
}

/** Composition root: wires adapters into the core and exposes the REST handlers. */
export function createApp(deps: AppDeps = {}): App {
  const eventPublisher = deps.eventPublisher ?? new KafkaEventPublisher();
  const service = new OrderService({
    orders: deps.orderRepository ?? new InMemoryOrderRepository(),
    events: eventPublisher,
    payments: deps.paymentGateway ?? new HttpPaymentGateway(),
    clock: deps.clock ?? new SystemClock(),
    ids: deps.idGenerator ?? new RandomIdGenerator(),
  });
  const controller = createOrdersController(service);

  return {
    handle: (method, path, body) => controller.handle({ method, path, body }),
    events: eventPublisher,
  };
}

